import json,collections,numpy as np
from dojo.skills.geometry import T_from
from dojo.skills import grasps as G
from dojo.skills.kinematics import gap_to_grip
from dojo.simlab import paths
def band(obj):
 V=obj.asset.mesh[0];raw=obj.asset.active_functional['headband_bridge']['frame'][0];H=T_from(raw[:3],quat=raw[3:]);L=(V-H[:3,3])@H[:3,:3];out=[]
 for x in [0.,-.035,.035,-.055,.055,-.065,.065]:
  p=L[(abs(L[:,0]-x)<.007)&(abs(L[:,1])<.03)&(L[:,2]>-.045)]
  if len(p)<4:continue
  lo,hi=p.min(0),p.max(0);c=(lo+hi)/2;c[0]=x
  for closing_ax,approach_ax in [(2,1),(1,2)]:
   for sign in (-1,1):
    for tangent in (0.,-.4,.4):
     app=sign*np.eye(3)[approach_ax]+tangent*np.eye(3)[0];app=app/np.linalg.norm(app)
     A=obj.R@H[:3,:3]@app
     if A[2]>.05:continue
     for flip in (-1,1):
      T=T_from(obj.T[:3,:3]@(H[:3,:3]@c+H[:3,3])+obj.pos,G._frame(A,obj.R@H[:3,:3]@(flip*np.eye(3)[closing_ax])))
      w=G.mesh_width_at(obj,T,depths=(0.,.004,.008),max_normal_deg=45.)
      if w is None or not (.003<=w<=.084):continue
      out.append(G.Grasp('antipodal',T,w,pre_dist=.05,score=.1+abs(x),note=f'band x{x:.3f} ax{closing_ax} w{w*1000:.1f}'))
 return out

obj=sk.world.obj('headset');gg=band(obj);out={'pos':obj.pos.tolist(),'R':obj.R.tolist(),'sites':[],'arms':{}}
for g in gg:out['sites'].append({'note':g.note,'pos':g.T[:3,3].tolist(),'approach':g.T[:3,0].tolist(),'closing':g.T[:3,1].tolist()})
for a in ('left','right'):
 c=collections.Counter();examples=[]
 for g in gg:
  r=sk.kin.ik(a,g.T,sk.ex.q[a],n_random=0)
  if not r.ok:c['ik_fail']+=1;continue
  ok,why=sk.coll.check(a,r.q,gap_to_grip(g.open_gap()),ignore=('headset',));c[why or 'ok']+=1
  examples.append({'note':g.note,'q':r.q.tolist(),'why':why})
 out['arms'][a]={'counts':dict(c),'examples':examples}
(paths.DATA/'round2d-band-diag66.json').write_text(json.dumps(out,indent=2));print('BAND_DIAG',json.dumps(out),flush=True)

